import{_ as t,c as o,o as s,ag as a}from"./chunks/framework.3IuuWm4t.js";const p=JSON.parse('{"title":"GitLab Hexo 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/gitlab-gitlabhexo.md","filePath":"platforms/gitlab-gitlabhexo.md","lastUpdated":1795809563000}'),d={name:"platforms/gitlab-gitlabhexo.md"};function i(r,e,c,l,n,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="gitlab-hexo-配置指南" tabindex="-1">GitLab Hexo 配置指南 <a class="header-anchor" href="#gitlab-hexo-配置指南" aria-label="Permalink to &quot;GitLab Hexo 配置指南&quot;">​</a></h1><p>通过 <strong>GitLab API</strong> 将文章发布到 GitLab 上的 <strong>Hexo</strong> 博客仓库。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可作为 Hexo 博客仓库的 <strong>GitLab 仓库</strong>（如 <code>hexo-blog</code>）。</li><li>一个对该仓库有 <strong>push 权限</strong> 的 <strong>GitLab 个人访问令牌（Personal Access Token）</strong>（GitLab 右上角头像 → Preferences → Access Tokens，或访问 <code>/-/user_settings/personal_access_tokens</code>，勾选 <code>api</code> 或 <code>write_repository</code> 范围）。</li><li>该仓库是一个标准 Hexo 项目（含 <code>_config.yml</code> 与 <code>source/</code> 目录）；如使用 GitLab Pages，仓库已配置对应的构建流水线。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>你的 GitLab 实例地址（自建实例填自己的域名，如 <code>https://gitlab.example.com</code>），用于拼出仓库地址</td></tr><tr><td>API 地址</td><td>GitLab API 地址，<strong>与平台首页一致</strong>；填写平台首页后会自动同步为该地址，平台首页留空时该地址也会被清空</td></tr><tr><td>用户名</td><td>GitLab 用户名（owner），用于拼出仓库地址</td></tr><tr><td>鉴权 Token</td><td>GitLab 个人访问令牌（Personal Access Token），需对目标仓库有 push 权限</td></tr><tr><td>git 仓库名</td><td>Hexo 博客仓库名，与用户名组成 <code>&lt;user&gt;/&lt;repo&gt;</code>，如 <code>hexo-blog</code></td></tr><tr><td>默认分支</td><td>发布到的分支，默认 <code>main</code>，需与仓库实际分支一致</td></tr><tr><td>存储目录</td><td>Hexo 文章存储目录，默认 <code>source/_posts</code>。发布后的 <code>.md</code> 会写入该目录</td></tr><tr><td>文件规则</td><td>文章文件名规则，默认 <code>[slug].md</code>（文章别名）</td></tr><tr><td>文章预览规则</td><td>站点文章预览规则，默认 <code>/post/[postid].html</code>。Hexo 站点地址由构建后的永久链接规则决定，此规则仅作查看参考</td></tr><tr><td>预览规则</td><td>GitLab blob 预览规则，固定 <code>/[user]/[repo]/blob/[branch]/[docpath]</code>，查看链接即该 <code>.md</code> 在仓库中的地址，<strong>不支持修改</strong></td></tr><tr><td>发布目录</td><td>默认 <code>source/_posts</code>。该平台<strong>不支持修改发布目录</strong>（配置页为只读提示），如需更换请删除账号后重新发布</td></tr><tr><td>YAML 永久链接</td><td>提供该开关；开启后把文章永久链接写入 Front Matter，供站点按自定义链接生成页面</td></tr><tr><td>图床</td><td>默认「当前平台」：图片提交到仓库 <code>source/images</code>，文章引用相对路径 <code>../images/&lt;图片名&gt;</code></td></tr></tbody></table><p>发布写入的 Front Matter 含 <code>title</code>、<code>date</code>、<code>updated</code>、<code>excerpt</code>、<code>tags</code>、<code>categories</code>（可在「YAML 预设配置」中覆盖）。</p><p>「YAML 预设配置」留空时，Hexo 平台会写入以下默认值：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">comments</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">toc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>填入 JSON 片段（例如 <code>{&quot;toc&quot;: false}</code>）时，改为逐键合并进 Front Matter。</p><h2 id="三、图片约定-hexo-静态资源目录" tabindex="-1">三、图片约定（Hexo 静态资源目录） <a class="header-anchor" href="#三、图片约定-hexo-静态资源目录" aria-label="Permalink to &quot;三、图片约定（Hexo 静态资源目录）&quot;">​</a></h2><ul><li><code>imageStorePath = source/images</code> 是<strong>仓库根目录</strong>下的固定路径（不随文章目录变化），图片提交到该目录。</li><li><code>imageLinkPath = ../images</code> 生成<strong>相对文章所在目录</strong>的引用 <code>../images/&lt;图片名&gt;</code>（文章位于 <code>source/_posts</code>，因此解析到 <code>source/images</code>）。</li><li>Hexo 构建时会把 <code>source/images</code> 复制到站点根目录，文章页面位于站点根下一层，因此 <code>../images/&lt;图片名&gt;</code> 在<strong>源码编辑器与构建产物中都能显示</strong>。</li><li>发布带图文章后，仓库中会同时出现 <code>source/_posts/&lt;文件名&gt;.md</code> 与 <code>source/images/&lt;图片名&gt;</code>。</li></ul><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 令牌、仓库、分支校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 GitLab Hexo → 发布。文章 <code>.md</code> 提交到 <code>source/_posts/[slug].md</code>。</li><li>「查看文章」打开仓库 blob 地址；站点线上地址由 Hexo 构建决定，需站点已构建部署。</li><li>带图发布时图片提交到 <code>source/images</code>，文章引用 <code>../images/&lt;图片名&gt;</code>。</li></ol><p>2.4.0 起，「YAML 预设配置」支持日期、标题、别名、标签与分类占位符；2.5.0 起支持 <code>[attr:属性名]</code> 文档属性占位符与 <code>[cover]</code> 封面占位符。预设仅在首次生成平台 YAML 时应用，已发布文章的更新沿用已保存的 YAML。完整语法与修改已有文章的方法见 <a href="/siyuan-plugin-publisher/guide/single-publish.html#yaml-预设配置">YAML 预设配置</a>。</p><h2 id="五、封面图" tabindex="-1">五、封面图 <a class="header-anchor" href="#五、封面图" aria-label="Permalink to &quot;五、封面图&quot;">​</a></h2><p>详细发布模式提供可选的「封面图」，三种填写方式任选：</p><ul><li><strong>上传图片</strong>：从本机选图，先存进思源资源库（<code>assets/</code>），发布时随文章提交到仓库图片目录；</li><li><strong>填写图片地址</strong>：支持完整图片链接，或已经存在的站内路径；</li><li><strong>取正文首图</strong>：直接引用正文第一张图片。</li></ul><p>发布时，思源资源图片会提交到「图片存储目录」（默认 <code>source/images</code>），并把平台可用地址写入文章 Front Matter 的 <code>cover</code> 字段；留空则不设置封面。更新时会回填上次选择；清空后更新会移除该字段。封面处理失败只提示，不影响正文发布。</p><p>Hexo 本身不定义封面字段，由主题读取。插件默认写 <code>cover</code>（Butterfly 等主题直接使用）；主题使用其它字段（如 Fluid 的 <code>index_img</code>、<code>banner_img</code>）时，在「YAML 预设配置」里用 <code>[cover]</code> 映射：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;index_img&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[cover]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;banner_img&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[cover]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>使用 <code>[cover]</code> 映射后，插件不再额外写默认 <code>cover</code>；没有设置封面时，对应字段会被省略。GitLab 平台的图片地址是仓库 raw 链接，仓库需对站点访问者可见（私有仓库的 raw 链接需要登录）。</p><h2 id="六、详细模式的元数据" tabindex="-1">六、详细模式的元数据 <a class="header-anchor" href="#六、详细模式的元数据" aria-label="Permalink to &quot;六、详细模式的元数据&quot;">​</a></h2><p>详细模式里的标题、摘要、标签、分类、发布时间和更新时间默认跟随当前思源文档；文档没有填写的字段保留平台侧已有值。如果某个字段在详细模式里手动改过并更新，插件会把它记为该平台的覆盖值，再次打开时优先显示覆盖值，不会被文档内容覆盖。把覆盖字段改回思源文档里的值并发布后，覆盖会自动移除。</p><p>源码模式直接编辑 YAML，以编辑器里的值为准。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证通过但发布失败</strong>：确认个人访问令牌对目标仓库有 push 权限（<code>api</code> 或 <code>write_repository</code> 范围），仓库名与分支填写正确。权限不足会收到 401/403。</li><li><strong>自建 GitLab 该怎么填平台首页</strong>：平台首页填你的实例地址（如 <code>https://gitlab.example.com</code>），API 地址会同步为该地址；令牌地址同样由实例地址拼出（<code>/-/user_settings/personal_access_tokens</code>），需在你自己实例的偏好设置里生成令牌。</li><li><strong>图片要怎么发布</strong>：图床默认「当前平台」，图片提交到仓库 <code>source/images</code>，文章中引用相对路径 <code>../images/&lt;图片名&gt;</code>；Hexo 构建后该目录会复制到站点根目录，源码与构建产物均可正常显示。</li><li><strong>封面图怎么设置</strong>：详细发布模式填写「封面图」后发布即可；主题封面字段不是 <code>cover</code> 时，用「YAML 预设配置」的 <code>[cover]</code> 映射到主题字段。</li><li><strong>封面图不显示</strong>：先确认主题使用的 Front Matter 字段名；默认写 <code>cover</code>，若主题使用 <code>index_img</code>、<code>banner_img</code> 等字段，需要加 <code>[cover]</code> 映射后重新发布。</li><li><strong>详细模式里改了标题/标签/更新时间，重新打开又变回文档内容？</strong> 详细模式默认跟随思源文档；手动改过并更新后，插件会把这几个字段记为该平台的覆盖值，之后打开优先显示覆盖值。把字段改回文档值并发布后，覆盖会自动移除；源码模式直接编辑 YAML，以编辑器为准。</li><li><strong>查看链接打不开</strong>：查看链接为仓库中该 <code>.md</code> 的 blob 地址（<code>/[user]/[repo]/blob/[branch]/[docpath]</code>），仓库中存在该文件即可打开，需已登录 GitLab 且对该仓库有访问权限；该规则固定，不支持修改。</li><li><strong>发布目录能不能改</strong>：不能，固定为存储目录（默认 <code>source/_posts</code>）；如需更换请删除账号后重新发布。</li><li><strong>线上没有新文章</strong>：Hexo 是通过构建（<code>hexo generate</code>）从 <code>source/</code> 生成站点的，仅推送 <code>.md</code> 不会直接改变已部署站点；确认仓库已配置自动构建（GitLab CI / Pages 等）并触发一次构建。</li><li><strong>更新与删除</strong>：点「更新」会重新提交该文章并产生一次新提交；「删除」会移除仓库中对应的 <code>.md</code>，站点需重新构建才会同步下线。</li></ul>`,27)])])}const u=t(d,[["render",i]]);export{p as __pageData,u as default};
